impl flatbuffers::Verifiable for Response<'_> {
  #[inline]
  fn run_verifier(
    v: &mut flatbuffers::Verifier, pos: usize
  ) -> Result<(), flatbuffers::InvalidFlatbuffer> {
    use self::flatbuffers::Verifiable;
    v.visit_table(pos)?
     .visit_field::<u64>("version", Self::VT_VERSION, false)?
     .visit_field::<u64>("req_id", Self::VT_REQ_ID, false)?
     .visit_field::<Status>("status", Self::VT_STATUS, false)?
     .visit_field::<flatbuffers::ForwardsUOffset<&str>>("message", Self::VT_MESSAGE, false)?
     .visit_union::<ResponseBody, _>("body_type", Self::VT_BODY_TYPE, "body", Self::VT_BODY, false, |key, v, pos| {
        match key {
          ResponseBody::InsertRes => v.verify_union_variant::<flatbuffers::ForwardsUOffset<InsertRes>>("ResponseBody::InsertRes", pos),
          ResponseBody::FindRes => v.verify_union_variant::<flatbuffers::ForwardsUOffset<FindRes>>("ResponseBody::FindRes", pos),
          ResponseBody::CountRes => v.verify_union_variant::<flatbuffers::ForwardsUOffset<CountRes>>("ResponseBody::CountRes", pos),
          ResponseBody::ExistsRes => v.verify_union_variant::<flatbuffers::ForwardsUOffset<ExistsRes>>("ResponseBody::ExistsRes", pos),
          ResponseBody::UpdateRes => v.verify_union_variant::<flatbuffers::ForwardsUOffset<UpdateRes>>("ResponseBody::UpdateRes", pos),
          ResponseBody::ReplaceRes => v.verify_union_variant::<flatbuffers::ForwardsUOffset<ReplaceRes>>("ResponseBody::ReplaceRes", pos),
          ResponseBody::DeleteRes => v.verify_union_variant::<flatbuffers::ForwardsUOffset<DeleteRes>>("ResponseBody::DeleteRes", pos),
          ResponseBody::SearchRes => v.verify_union_variant::<flatbuffers::ForwardsUOffset<SearchRes>>("ResponseBody::SearchRes", pos),
          ResponseBody::GroupRes => v.verify_union_variant::<flatbuffers::ForwardsUOffset<GroupRes>>("ResponseBody::GroupRes", pos),
          ResponseBody::StatsRes => v.verify_union_variant::<flatbuffers::ForwardsUOffset<StatsRes>>("ResponseBody::StatsRes", pos),
          ResponseBody::IndexRes => v.verify_union_variant::<flatbuffers::ForwardsUOffset<IndexRes>>("ResponseBody::IndexRes", pos),
          _ => Ok(()),
        }
     })?
     .finish();
    Ok(())
  }
}
